-- English copy for the seed's catalogue.
--
-- goen never invents a translation — CLAUDE.md's editorial line stands — but a dev
-- catalogue that leaves the products untranslated makes the English site look broken
-- when it is working exactly as designed. These are what a shop would type.
--
-- Only name and summary. The DESCRIPTION is the half somebody has to sit down and
-- write, and leaving it untranslated here is the honest demonstration of the
-- fallback: an English visitor reads an English name, an English summary and a
-- Chinese description, which is what a half-translated product looks like on
-- purpose.
UPDATE products p SET name_en = m.name_en, summary_en = m.summary_en
FROM (VALUES
    ('pixelight-9-pro', 'Pixelight 9 Pro 5G',
     'The flagship camera, a titanium frame and an LTPO display.'),
    ('pixelight-9', 'Pixelight 9 5G',
     'The flagship experience at a friendlier price.'),
    ('pixelight-9-pro-case', 'Pixelight 9 Pro Case',
     'Clear case with a military drop rating.'),
    ('aurora-edge-7', 'Aurora Edge 7',
     'Curved display, fast charging, a full day of battery.'),
    ('aurora-slate-11', 'Aurora Slate 11',
     'A light tablet with stylus support.'),
    ('aurora-charger-65', 'Aurora GaN 65W Charger',
     'Two-port GaN fast charging for phones and laptops alike.'),
    ('meridian-book-14', 'Meridian Book 14',
     'A 14-inch metal body, thin and light, with all-day battery.'),
    ('meridian-book-16-pro', 'Meridian Book 16 Pro',
     'A mobile workstation for people who make things.'),
    ('meridian-book-sleeve-14', 'Meridian Laptop Sleeve 14"',
     'Wool felt sleeve, scratch and splash resistant.'),
    ('meridian-watch-s3', 'Meridian Watch S3',
     'A smartwatch that measures your health around the clock.'),
    ('koto-over-ear', 'Koto Over-Ear Quiet',
     'Over-ear noise cancelling with a warm, wooden tuning.'),
    ('koto-pad-mini', 'Koto Pad mini',
     'Small enough to hold in one hand.'),
    ('koto-cable-braided', 'Koto Braided USB-C Cable 2m',
     'A braided cable that survives being folded, up to 100W.'),
    ('nimbus-buds-pro', 'Nimbus Buds Pro',
     'True wireless earbuds with active noise cancelling.'),
    ('nimbus-band-2', 'Nimbus Band 2',
     'A light band that tracks sleep and heart rate.')
) AS m(slug, name_en, summary_en)
WHERE p.slug = m.slug;

-- Warranty terms, per product and deliberately not all the same.
--
-- This is the whole reason products.warranty_months is a column rather than a
-- site-wide setting: a phone and a braided cable do not carry the same cover.
-- Registration is REFUSED while it is NULL, so the two accessories below are left
-- unset on purpose — an untouched shop that has not thought about warranties should
-- see the honest refusal, not a term goen invented.
UPDATE products p SET warranty_months = m.months
FROM (VALUES
    ('pixelight-9-pro', 24), ('pixelight-9', 24), ('aurora-edge-7', 24),
    ('aurora-slate-11', 24), ('koto-pad-mini', 24),
    ('meridian-book-14', 24), ('meridian-book-16-pro', 36),
    ('meridian-watch-s3', 24), ('nimbus-band-2', 12),
    ('koto-over-ear', 12), ('nimbus-buds-pro', 12),
    ('aurora-charger-65', 12), ('koto-cable-braided', 6)
) AS m(slug, months)
WHERE p.slug = m.slug;

