-- English labels for the seed's option axes and their values.
--
-- These are LABELS. The variant picker puts the choice in the URL and the URL
-- carries the canonical Chinese value, so translating 星霧藍 changes what a visitor
-- READS and never what a link SELECTS — which is why display and identity are two
-- columns. Numeric values (256GB) need no translation and get none: the read falls
-- back, and a NULL means "same in both languages" exactly as it means "not done
-- yet".
UPDATE product_options SET name_en = 'Colour' WHERE name = '顏色';
UPDATE product_options SET name_en = 'Capacity' WHERE name = '容量';

UPDATE product_option_values v SET value_en = m.en
FROM (VALUES
    ('星霧藍', 'Mist Blue'), ('曜石黑', 'Obsidian Black'), ('曙光金', 'Dawn Gold'),
    ('午夜灰', 'Midnight Grey'), ('天空藍', 'Sky Blue'), ('太空銀', 'Space Silver'),
    ('櫻花粉', 'Sakura Pink'), ('玫瑰金', 'Rose Gold'), ('珊瑚橘', 'Coral Orange'),
    ('薄荷綠', 'Mint Green'), ('墨綠', 'Ink Green'), ('石墨灰', 'Graphite Grey'),
    ('石墨黑', 'Graphite Black'), ('炭黑', 'Charcoal'), ('雲白', 'Cloud White'),
    ('燕麥', 'Oat'), ('胡桃', 'Walnut'), ('透明', 'Clear'), ('霧透', 'Frosted'),
    ('銀', 'Silver'), ('黑', 'Black')
) AS m(zh, en)
WHERE v.value = m.zh;

